const D = { energy:.62, scale:1, speed:1, tilt:.72, beam:.55, hue:30, x:.5, y:.5, style:'thermal', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const style = P.style, sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- adaptive field buffer ----
const BW = Math.max(360, Math.min(560, Math.round(width / 3.0)));
const BH = Math.max(120, Math.round(BW * height / width));
if (!S.gfx || S.bw !== BW || S.bh !== BH) { S.gfx = createGraphics(BW, BH); S.gfx.pixelDensity(1); S.bw = BW; S.bh = BH; }
const g = S.gfx;

// seeded hotspot azimuths/radii/strengths
const NHS = 5;
if (S.hsSeed !== sd) { S.hsSeed = sd; S.hp = []; S.hr = []; S.hs = []; S.hm = [];
  for (let k = 0; k < NHS; k++) { S.hp.push(fr(k*4+1)*6.2831); S.hr.push(0.35+fr(k*4+2)*0.55); S.hs.push(0.5+fr(k*4+3)*0.5); S.hm.push(1+Math.floor(fr(k*4+4)*3)); } }

const T = K.t * (0.5 + P.speed * 0.85);
const incl = 0.35 + P.tilt * 1.05;                        // inclination (rad); higher = more edge-on
const ci = Math.cos(incl), si = Math.sin(incl);
const pa = 0.2 * Math.sin(T * 0.03) + T * 0.008;          // slow position-angle precession
const cpa = Math.cos(pa), spa = Math.sin(pa);
const Rout = 0.44 * u * (0.7 + P.scale * 0.55);           // outer radius in canvas px
const RoutB = Rout * BW / width;                          // in buffer px
const rin = 0.16;                                          // inner truncation (small — bare disk, not a shadow)
const cxB = (0.5 + (P.x - 0.5) * 0.5) * BW, cyB = (0.5 + (P.y - 0.5) * 0.5) * BH;
const beta = 0.25 + P.beam * 0.6;                          // beaming velocity fraction
const expo = 0.6 + P.energy * 1.5;
const gain = 1 + K.swell * 0.12 + A.rms * 0.25 + K.pulse * 0.1;
const hueBias = 0.12 * Math.cos((P.hue - 210) * Math.PI / 180);  // cool hue -> hotter/bluer disk

// blackbody-ish ramp: ct 0(cool red)->1(hot blue), returns [r,g,b] 0..255 * intensity done by caller
function ramp(ct, out) {
  let r, gg, b;
  if (ct < 0.28) { const s = ct / 0.28; r = 90 + s * 150; gg = 20 + s * 90; b = 8 + s * 20; }
  else if (ct < 0.52) { const s = (ct - 0.28) / 0.24; r = 240 + s * 15; gg = 110 + s * 120; b = 28 + s * 90; }
  else if (ct < 0.74) { const s = (ct - 0.52) / 0.22; r = 255 - s * 20; gg = 230 + s * 20; b = 118 + s * 120; }
  else { const s = (ct - 0.74) / 0.26; r = 235 - s * 90; gg = 250 - s * 40; b = 238 + s * 17; }
  out[0] = r; out[1] = gg; out[2] = b;
}
const col = [0, 0, 0];

g.loadPixels(); const pix = g.pixels;
const dopW = style === 'doppler' ? 0.5 : (style === 'iron' ? 0.34 : 0.2);
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    const o = 4 * (j * BW + i);
    // screen coords rel center, undo position angle
    let sx = (i - cxB) / RoutB, sy = (j - cyB) / RoutB;
    let rx = sx * cpa + sy * spa, ry = -sx * spa + sy * cpa;
    // de-project inclination (screen y compressed by cos incl)
    const py = ry / (ci + 1e-3);
    const r = Math.sqrt(rx * rx + py * py);
    if (r < rin * 0.6 || r > 1.06) {
      // deep-space ground w/ faint outer disk haze
      const haze = Math.max(0, 1.06 - r) * (r > 1 ? 0.5 : 0);
      pix[o] = 6 + haze * 30; pix[o + 1] = 7 + haze * 16; pix[o + 2] = 12 + haze * 8; pix[o + 3] = 255; continue;
    }
    const phi = Math.atan2(py, rx);
    // Keplerian differential rotation
    const vr = 1 / Math.sqrt(Math.max(rin, r));
    const vnorm = vr / (1 / Math.sqrt(rin));               // 0..1
    // line-of-sight velocity for beaming (approaching side brighter/bluer)
    const los = Math.cos(phi) * si * vnorm;
    // turbulence: spiral density waves + orbiting hotspots advecting with omega(r)
    const omega = 2.4 * Math.pow(r, -1.5);
    let turb = 0.55 + 0.25 * Math.sin(2 * phi - omega * T * 0.6 + r * 6)
                    + 0.18 * Math.sin(3 * phi + omega * T * 0.4);
    for (let k = 0; k < NHS; k++) {
      const hp = S.hp[k] - S.hs[k] * Math.pow(S.hr[k], -1.5) * T * 0.5;
      const dphi = Math.atan2(Math.sin(phi - hp), Math.cos(phi - hp));
      const dr = r - S.hr[k];
      turb += S.hs[k] * 0.5 * Math.exp(-(dphi * dphi) * 6 - (dr * dr) * 22);
    }
    // radial emission profile (bright inner, fade out) + inner-edge rim
    let emit = Math.pow(rin / r, 1.7) * 0.9 + Math.exp(-(r - rin) * (r - rin) * 40) * 0.6;
    emit *= (r < 1 ? 1 : Math.max(0, 1.06 - r) * 3);       // soft outer edge
    // relativistic beaming
    const beamF = Math.pow(Math.max(0.08, 1 + beta * los), 3);
    let I = emit * Math.max(0, turb) * beamF * expo * gain;
    // color temperature: hotter inner + doppler shift
    let ct = 0.30 + (1 - r) * 0.42 + los * dopW + hueBias;
    if (ct < 0) ct = 0; else if (ct > 1) ct = 1;
    ramp(ct, col);
    if (style === 'contour') {                             // schematic iso-emission streamlines
      const band = Math.pow(0.5 + 0.5 * Math.cos(Math.log(1 + I) * 9.0 + phi * 0), 6);
      I = (0.12 + band * 0.9) * Math.min(1.4, I);
      col[0] = 120; col[1] = 200 + los * 40; col[2] = 255;
    }
    let R = col[0] * I, G = col[1] * I, B = col[2] * I;
    pix[o] = R > 255 ? 255 : R; pix[o + 1] = G > 255 ? 255 : G; pix[o + 2] = B > 255 ? 255 : B; pix[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
noTint();
// bright central compact object (boundary layer) — NOT a black-hole shadow
blendMode(ADD); noStroke();
const ccx = (0.5 + (P.x - 0.5) * 0.5) * width, ccy = (0.5 + (P.y - 0.5) * 0.5) * height;
const tw = 0.8 + 0.2 * Math.sin(T * 0.9) + K.pulse * 0.2 + A.bass * 0.3;
if (style !== 'contour') {
  fill(48, 12, 100, (14 + P.energy * 16) * (P.alpha / 100));
  circle(ccx, ccy, Rout * rin * 1.6 * tw);
  fill(50, 4, 100, (26 + P.energy * 18) * (P.alpha / 100));
  circle(ccx, ccy, Rout * rin * 0.7);
}
blendMode(BLEND);
pop();
